<template>
  <div class="equipment-page">
    <section class="equipment-hero"><div><span>EQUIPMENT & SPARE PARTS</span><h2>设备备件关系库</h2><p>按设备查看常用备件、实时库存和维修工单，领用时留下可追溯对象。</p></div><div><el-button class="light-button" :loading="loading" @click="load"><el-icon><Refresh /></el-icon>刷新</el-button><el-button v-if="isAdmin" type="primary" @click="createVisible=true"><el-icon><Plus /></el-icon>新增设备</el-button></div></section>

    <section class="equipment-summary">
      <article><span>设备台账</span><strong>{{ equipment.length }}</strong><small>当前已建档设备</small></article>
      <article><span>备件关系</span><strong>{{ relationCount }}</strong><small>设备与备件关联数</small></article>
      <article class="is-alert"><span>进行中工单</span><strong>{{ openOrderCount }}</strong><small>维修与保养任务</small></article>
    </section>

    <section class="panel equipment-panel">
      <div class="equipment-toolbar"><div><strong>设备列表</strong><span>点击设备查看备件和工单</span></div><el-input v-model="keyword" clearable placeholder="搜索编码、名称或工段" style="width:min(340px,100%)"><template #prefix><el-icon><Search /></el-icon></template></el-input></div>
      <div v-if="filtered.length" class="equipment-grid">
        <button v-for="item in filtered" :key="item.id" type="button" @click="openDetail(item)"><span class="equipment-icon"><el-icon><SetUp /></el-icon></span><div><small>{{ item.workshopGroup || '未分工段' }}</small><strong>{{ item.equipmentName }}</strong><em>{{ item.equipmentCode }} · {{ item.location || '位置未填写' }}</em></div><dl><div><dt>关联备件</dt><dd>{{ item.partCount || 0 }}</dd></div><div><dt>进行中工单</dt><dd :class="{'danger':Number(item.openWorkOrders)>0}">{{ item.openWorkOrders || 0 }}</dd></div></dl><el-icon class="arrow"><ArrowRight /></el-icon></button>
      </div>
      <el-empty v-else description="暂无设备台账" />
    </section>

    <el-drawer v-model="detailVisible" title="设备详情" size="min(820px, 96vw)">
      <template v-if="detail">
        <div class="detail-hero"><div><h2>{{ detail.equipmentName }}</h2><p>{{ detail.equipmentCode }} · {{ detail.workshopGroup || '未分工段' }} · {{ detail.location || '位置未填写' }}</p></div><el-tag type="success" size="large" round>在用</el-tag></div>
        <div class="drawer-section"><div class="section-title"><h3>关联备件</h3><el-button v-if="isAdmin" link type="primary" @click="openLink"><el-icon><Plus /></el-icon>关联备件</el-button></div><el-table :data="detail.parts" border empty-text="尚未关联备件"><el-table-column label="备件" min-width="250"><template #default="{row}"><div class="material-cell"><strong>{{ row.materialDesc }}</strong><span>{{ row.materialCode }} · {{ row.spec || '未填写规格' }}</span></div></template></el-table-column><el-table-column label="库存" width="110" align="center"><template #default="{row}"><strong>{{ row.totalStock }} {{ row.unit }}</strong></template></el-table-column><el-table-column label="单台用量" width="110" align="center"><template #default="{row}">{{ row.quantityPerEquipment ?? '-' }} {{ row.unit }}</template></el-table-column></el-table></div>
        <div class="drawer-section"><div class="section-title"><h3>维修工单</h3><el-button v-if="isAdmin" link type="primary" @click="workVisible=true"><el-icon><Plus /></el-icon>创建工单</el-button></div><div class="work-orders"><article v-for="order in detail.workOrders" :key="order.id"><span class="work-state" :class="`is-${order.status}`"></span><div><strong>{{ order.title }}</strong><small>{{ order.orderNo }} · {{ formatTime(order.openedAt) }}</small></div><div class="work-actions"><el-tag :type="order.status==='completed'?'success':'warning'" effect="light">{{ order.status==='completed'?'已完成':'进行中' }}</el-tag><el-button v-if="isAdmin&&order.status!=='completed'" link type="success" @click="completeWork(order)">完成</el-button></div></article><el-empty v-if="!detail.workOrders?.length" :image-size="50" description="暂无维修工单" /></div></div>
      </template>
    </el-drawer>

    <el-dialog v-model="createVisible" title="新增设备" width="min(600px, 94vw)" destroy-on-close><el-form label-position="top"><div class="form-grid"><el-form-item label="设备编码" required><el-input v-model="equipmentForm.equipmentCode" /></el-form-item><el-form-item label="设备名称" required><el-input v-model="equipmentForm.equipmentName" /></el-form-item><el-form-item label="所属工段"><el-input v-model="equipmentForm.workshopGroup" placeholder="例如：输送工段" /></el-form-item><el-form-item label="设备位置"><el-input v-model="equipmentForm.location" /></el-form-item></div><el-form-item label="备注"><el-input v-model="equipmentForm.notes" type="textarea" :rows="2" /></el-form-item></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveEquipment">保存</el-button></template></el-dialog>

    <el-dialog v-model="linkVisible" title="关联常用备件" width="min(720px, 94vw)" destroy-on-close><el-input v-model="partKeyword" clearable placeholder="输入物料编码、名称或规格" @keyup.enter="searchParts"><template #append><el-button :loading="partLoading" @click="searchParts"><el-icon><Search /></el-icon></el-button></template></el-input><el-table :data="partCandidates" v-loading="partLoading" border max-height="300" style="margin-top:14px"><el-table-column label="备件" min-width="290"><template #default="{row}"><div class="material-cell"><strong>{{ row.materialDesc }}</strong><span>{{ row.materialCode }} · {{ row.spec || '未填写规格' }}</span></div></template></el-table-column><el-table-column label="库存" width="100" align="center"><template #default="{row}">{{ row.totalStock }} {{ row.unit }}</template></el-table-column><el-table-column label="操作" width="90" align="right"><template #default="{row}"><el-button link type="primary" @click="selectPart(row)">选择</el-button></template></el-table-column></el-table><template v-if="selectedPart"><div class="selected-link"><strong>{{ selectedPart.materialDesc }}</strong><el-input-number v-model="linkQuantity" :min="0" controls-position="right" /><span>{{ selectedPart.unit || '个' }}/台</span></div></template><template #footer><el-button @click="linkVisible=false">取消</el-button><el-button type="primary" :disabled="!selectedPart" :loading="saving" @click="saveLink">确认关联</el-button></template></el-dialog>

    <el-dialog v-model="workVisible" title="创建维修工单" width="min(520px, 92vw)" destroy-on-close><el-form label-position="top"><el-form-item label="工单标题" required><el-input v-model="workForm.title" placeholder="例如：1号输送机轴承异响检修" /></el-form-item><el-form-item label="任务说明"><el-input v-model="workForm.notes" type="textarea" :rows="3" /></el-form-item></el-form><template #footer><el-button @click="workVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveWorkOrder">创建</el-button></template></el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { createEquipment, createMaintenanceWorkOrder, getEquipment, getEquipmentDetail, getParts, linkEquipmentPart, updateMaintenanceWorkOrderStatus } from '../api'
import { getUser } from '../auth'
const loading=ref(false),equipment=ref([]),keyword=ref(''),detailVisible=ref(false),detail=ref(null),createVisible=ref(false),linkVisible=ref(false),workVisible=ref(false),saving=ref(false),partKeyword=ref(''),partLoading=ref(false),partCandidates=ref([]),selectedPart=ref(null),linkQuantity=ref(1)
const equipmentForm=reactive({equipmentCode:'',equipmentName:'',workshopGroup:'',location:'',notes:''}),workForm=reactive({title:'',notes:''})
const isAdmin=getUser()?.role==='admin'
const filtered=computed(()=>{const key=keyword.value.trim().toLowerCase();return key?equipment.value.filter(item=>[item.equipmentCode,item.equipmentName,item.workshopGroup,item.location].some(v=>String(v||'').toLowerCase().includes(key))):equipment.value})
const relationCount=computed(()=>equipment.value.reduce((sum,item)=>sum+Number(item.partCount||0),0)),openOrderCount=computed(()=>equipment.value.reduce((sum,item)=>sum+Number(item.openWorkOrders||0),0))
function formatTime(v){return v?String(v).replace('T',' ').slice(0,16):'-'}
async function load(){loading.value=true;try{const result=await getEquipment();equipment.value=result.data||[]}finally{loading.value=false}}
async function refreshDetail(){if(!detail.value)return;const result=await getEquipmentDetail(detail.value.id);detail.value=result.data}
async function openDetail(item){const result=await getEquipmentDetail(item.id);detail.value=result.data;detailVisible.value=true}
async function saveEquipment(){if(!equipmentForm.equipmentCode.trim()||!equipmentForm.equipmentName.trim())return ElMessage.warning('请填写设备编码和名称');saving.value=true;try{await createEquipment({...equipmentForm});ElMessage.success('设备已创建');createVisible.value=false;Object.assign(equipmentForm,{equipmentCode:'',equipmentName:'',workshopGroup:'',location:'',notes:''});load()}finally{saving.value=false}}
function openLink(){partKeyword.value='';partCandidates.value=[];selectedPart.value=null;linkQuantity.value=1;linkVisible.value=true}
async function searchParts(){partLoading.value=true;try{const result=await getParts({page:1,pageSize:50,searchKeyword:partKeyword.value});partCandidates.value=result.data||[]}finally{partLoading.value=false}}
function selectPart(row){selectedPart.value=row}
async function saveLink(){saving.value=true;try{await linkEquipmentPart(detail.value.id,{inventoryId:selectedPart.value._id,quantityPerEquipment:linkQuantity.value});ElMessage.success('备件关系已建立');linkVisible.value=false;await Promise.all([refreshDetail(),load()])}finally{saving.value=false}}
async function saveWorkOrder(){if(!workForm.title.trim())return ElMessage.warning('请填写工单标题');saving.value=true;try{await createMaintenanceWorkOrder(detail.value.id,{...workForm});ElMessage.success('维修工单已创建');workVisible.value=false;Object.assign(workForm,{title:'',notes:''});await Promise.all([refreshDetail(),load()])}finally{saving.value=false}}
async function completeWork(order){await updateMaintenanceWorkOrderStatus(order.id,{status:'completed'});ElMessage.success('工单已完成');await Promise.all([refreshDetail(),load()])}
onMounted(load)
</script>

<style scoped>
.equipment-hero{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:16px;padding:26px 29px;border-radius:20px;color:#fff;background:linear-gradient(125deg,#7f131b,#b31d28 58%,#d13540);box-shadow:0 18px 42px #72121b2b}.equipment-hero>div:last-child{display:flex;gap:9px}.equipment-hero span{color:#ffc7cc;font-size:12px;font-weight:900;letter-spacing:.12em}.equipment-hero h2{margin:7px 0 0;font-size:28px}.equipment-hero p{margin:7px 0 0;color:#ffffffc4;font-size:13px}.light-button{color:#fff!important;border-color:#ffffff45!important;background:#ffffff16!important}.equipment-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin-bottom:16px}.equipment-summary article{padding:18px 20px;border:1px solid #e2e6eb;border-left:4px solid #b11e28;border-radius:16px;background:#fff}.equipment-summary article:nth-child(2){border-left-color:#5575a5}.equipment-summary .is-alert{border-left-color:#d28c18}.equipment-summary span,.equipment-summary strong,.equipment-summary small{display:block}.equipment-summary span{color:#687386;font-size:12px;font-weight:800}.equipment-summary strong{margin-top:7px;font-size:27px}.equipment-summary small{margin-top:5px;color:#8a93a4;font-size:12px}.equipment-panel{padding:18px}.equipment-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:14px}.equipment-toolbar strong,.equipment-toolbar span{display:block}.equipment-toolbar span{margin-top:4px;color:#7c8798;font-size:12px}.equipment-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.equipment-grid>button{position:relative;display:grid;grid-template-columns:44px minmax(0,1fr);gap:12px;padding:17px;border:1px solid #e2e6eb;border-radius:15px;color:#263143;background:#fff;cursor:pointer;text-align:left;transition:.2s}.equipment-grid>button:hover{transform:translateY(-2px);border-color:#d9989e;box-shadow:0 12px 28px #8f172014}.equipment-icon{width:44px;height:44px;display:grid;place-items:center;border-radius:13px;color:#a51924;background:#fff0f1;font-size:22px}.equipment-grid small,.equipment-grid strong,.equipment-grid em{display:block}.equipment-grid small{color:#9a5a60;font-size:11px}.equipment-grid strong{margin-top:3px;font-size:15px}.equipment-grid em{margin-top:4px;overflow:hidden;color:#7b8595;font-size:12px;font-style:normal;text-overflow:ellipsis;white-space:nowrap}.equipment-grid dl{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0 0}.equipment-grid dl div{padding:9px;border-radius:9px;background:#f7f8fa}.equipment-grid dt{color:#808a99;font-size:11px}.equipment-grid dd{margin:3px 0 0;font-weight:800}.equipment-grid dd.danger{color:#c91f2c}.equipment-grid .arrow{position:absolute;right:14px;top:18px;color:#a3aab6}.section-title{display:flex;align-items:center;justify-content:space-between}.section-title h3{margin:0}.work-orders{border:1px solid #e6e9ee;border-radius:13px;overflow:hidden}.work-orders article{display:grid;grid-template-columns:10px 1fr auto;gap:11px;align-items:center;padding:13px;border-bottom:1px solid #eceff3}.work-orders article:last-child{border-bottom:0}.work-state{width:9px;height:9px;border-radius:50%;background:#e2a128}.work-state.is-completed{background:#18a473}.work-orders strong,.work-orders small{display:block}.work-orders small{margin-top:4px;color:#7e8795;font-size:11px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}.selected-link{display:grid;grid-template-columns:1fr 150px auto;gap:10px;align-items:center;margin-top:14px;padding:13px;border-radius:11px;background:#eefaf6}.selected-link strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}@media(max-width:1150px){.equipment-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:720px){.equipment-hero{align-items:stretch;flex-direction:column;padding:21px}.equipment-summary,.equipment-grid,.form-grid{grid-template-columns:1fr}.equipment-toolbar{align-items:stretch;flex-direction:column}.selected-link{grid-template-columns:1fr}.equipment-hero>div:last-child .el-button{flex:1}}
.work-actions{display:flex;align-items:center;gap:6px}
</style>
